from h34 import *
M=mcq;F=tf;S=short;N=num
b='<rect x="10" y="10" width="520" height="230" rx="10" fill="#f6fbf0" stroke="#333" stroke-width="2"/><text x="270" y="35" text-anchor="middle" font-weight="bold">A map of the mela ground</text>'
def bx(x,y,w,h,t,c): return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="8" fill="{c}" stroke="#333" stroke-width="2"/><text x="{x+w/2}" y="{y+h/2+5}" text-anchor="middle" font-size="14">{t}</text>'
b+=bx(30,55,110,40,"Entrance","#fff3d6")+bx(170,55,110,40,"Lost and Found","#dff0ff")+bx(310,55,100,40,"Toy stall","#ffe5d6")+bx(430,55,90,40,"Magic show","#f3e5ff")
b+=bx(30,125,110,40,"Ambulance","#ffd6d6")+bx(170,125,110,40,"Police jeep","#d6e4ff")+bx(310,125,100,40,"Food stalls","#fff3d6")+bx(430,125,90,40,"Water point","#d6f0ff")
b+=bx(30,185,110,40,"Fire engine","#ffd6d6")+bx(170,185,110,40,"Dustbins","#e5f5e0")+bx(310,185,100,40,"Giant wheel","#ffe5d6")+bx(430,185,90,40,"Merry-go-round","#fff3d6")
svgfile('c3-mela-map.svg',540,250,b)
chapter(3,'evs','going-to-the-mela','Going to the Mela',
 ("Preparing for the mela","The mela has finally come to town and Nita and Radha are getting ready to go. There is a lot of excitement. Dadiji, whose legs hurt, is persuaded to come too. Join the two families on their bus ride, their day at the mela and the safe way back home."),
 [("Preparing for the mela",["Nita and Radha are getting ready to go to the mela, and the whole house is excited. The mela is a little far from home, so they will go by bus.","Dadiji has a bad leg, so at first she says she cannot come. Nita's father promises that the family will take care of her, and Dadiji agrees to go.","Dadiji reminds the children to fill up their water bottles. A water bottle is something we should carry when we go out for a long day.","Their neighbours Sneha and Rohit are joining them, and Mohan Chacha, Nita's father's brother, and his family are arriving by train. A mela is a gathering of many people."]),
  ("Travelling by bus",["The families go to the bus stop and Nita's father helps Dadiji walk slowly, holding her hand, to the stop. We should always help elders who find it hard to walk.","In the bus the children are asked to sit on their seats and not to jump around. They are also told not to put their hands or heads out of the window, for safety.","The bus goes through the city and reaches the big parade ground where the mela is held.","We travel in many ways: on foot, by bus, train, autorickshaw, car, bicycle or boat. Mohan Chacha's family came by train and then by an autorickshaw."]),
  ("At the entrance",["At the entrance of the mela there is a map of the ground showing the stalls and where they are. A map helps us find our way.","Near the map an ambulance, a police jeep and a fire engine are parked, so help is ready for an accident, an illness or a fire.","There is also a 'Lost and Found' booth with volunteers. If someone gets lost, or loses something, they can go there.","Mohan Chacha and Rohit hurry to get a wheelchair for Dadiji, so that she can enjoy the mela without getting tired."]),
  ("Fun at the stalls",["Inside, the children see stalls with games, toys, sweets and many interesting things. They go to the toy stall and buy spinning tops, puppets, phirkis and dolls.","They ride on the merry-go-round and the giant wheel. Sneha and Radha buy bangles and other trinkets.","Then they go to see a magic show and enjoy it very much.","A mela has many workers, such as the toy seller, bangle seller, puppeteer, halwai who makes sweets, mehendi artist, police officer, firefighter, medical attendant and volunteer, and each one does a useful job."]),
  ("Eating and keeping clean",["Mohan Chacha says they have had a lot of fun and now they should eat. But before eating the children must wash their hands properly, and they go to the water point.","The children enjoy gol gappas, chaat, chhole kulche, hot jalebis with rabri, kulfi and many other tasty things.","After eating they make sure they put all the waste in the dustbin. We must keep a place clean wherever we go.","Washing hands before eating and using dustbins keeps us healthy and keeps the mela clean."]),
  ("The police dog and the Kumbh Mela",["As they leave, Dadiji points out someone accompanying a police officer. The children answer that it is a police dog.","Police dogs help the police to find lost things and people. They are trained and obey their handlers.","Kumbh Mela is the world's biggest festival. It is the largest gathering of people and is held on the banks of the rivers Ganga, Yamuna, Godavari and Shipra, once in 12 years, in Haridwar, Prayagraj, Nashik and Ujjain.","Melas bring people together to enjoy games, food, music and shopping, and to meet friends and relatives."]),
  ("Reading a sketch and staying safe",["A sketch or map shows where places are. We can find a house, a police station or the parade ground on it, and trace the route from one place to another.","We can draw our own sketch of the route from home to school and mark the places on the way.","To stay safe while travelling we sit properly in a vehicle, never put our hands or heads out of the window, and hold an elder's hand in a crowd.","We can look after our elders by helping them walk, offering them a seat, carrying their bag and talking politely to them."])],
 [("Find your way on a mela map: how do we reach the food stalls from the entrance?",[("Find the entrance on the map and put your finger on it.","We always begin from where we are."),("Move along the paths to the food stalls, noting what lies on the way, like the toy stall or the water point.","Noting places on the way helps us remember the route."),("Say the route aloud: 'From the entrance, go past the Lost and Found booth and the toy stall to the food stalls'.","Saying the route aloud makes it easier to follow and to tell somebody else.")]),
  ("Lost in a crowd: what should a child do?",[("Stop and stay where you are. Do not run around.","If you stay, the family can find you more easily."),("Look for a police officer, a volunteer or the Lost and Found booth and ask for help.","Helpers wear uniforms or badges and are trained to help."),("Tell them your name and your parents' names and wait until your family comes.","This helps the helper to find your family.")])],
 ("Tell a friend about the mela and how to stay safe there.",["Mela has stalls, rides, shows and food","Map, Lost and Found, ambulance, police and fire engine are there to help","Wash hands before eating and put waste in dustbins","Sit properly in the bus and help elders"],["A mela has nobody to help us if we get lost","It is fine to put our head out of the bus window","We can throw waste anywhere"]),
 ["A mela is a gathering of many people with stalls, rides, games and food.","A map and a Lost and Found booth help us find our way and lost things.","An ambulance, a police jeep and a fire engine are at the mela for safety.","Wash your hands before you eat and put waste in the dustbin.","In a vehicle, sit properly and keep hands and heads inside the window.","We should look after our elders and help them."],
 [M("gm-1",1,"How did Nita and Radha go to the mela?","By bus",[("By aeroplane","The mela was in the same town, not far enough for an aeroplane."),("By boat","They went through the city on a bus."),("On foot only","The mela was a little far, so they took a bus.")],"They took a bus to the parade ground.",None),
  M("gm-2",1,"What is the purpose of the 'Lost and Found' booth?","To help people who are lost or have lost something",[("To sell toys","Toys are sold at the toy stall."),("To give rides","Rides are the merry-go-round and giant wheel."),("To serve food","Food is served at the food stalls.")],"If someone is lost or loses something, volunteers at the booth help.",None),
  M("gm-3",1,"Why were an ambulance, a police jeep and a fire engine kept at the mela?","So help would be ready in an emergency",[("To give rides to children","They are not for rides."),("To decorate the mela","They are kept for help, not decoration."),("To sell things","They do not sell anything.")],"They are there for accidents, illness, safety and fire.",None),
  M("gm-4",1,"What did the children do before eating at the mela?","Washed their hands",[("Went on a ride","They washed their hands first."),("Slept","They were hungry and awake."),("Bought a doll","They bought toys before, not before eating.")],"Mohan Chacha told them to wash their hands properly at the water point.",None),
  F("gm-5",1,"At the mela, the children threw the waste on the ground.",False,"They put all the waste in the dustbin. We must keep places clean."),
  M("gm-6",2,"Why did Mohan Chacha and Rohit get a wheelchair?","For Dadiji, whose legs hurt",[("For the children to play","A wheelchair is not a toy."),("For the police dog","The wheelchair was for Dadiji."),("For the toy seller","It was for Dadiji so she would not get tired.")],"A wheelchair helps a person who finds it hard to walk.",None),
  M("gm-7",2,"Which is a safe way to travel in a bus?","Sit on the seat and keep hands inside the window",[("Jump on the seats","Jumping can cause injuries when the bus moves."),("Put your head out to see","Your head can hit something."),("Stand near the door while it moves","It is not safe.")],"The father told the children to sit and not put their heads or hands out of the window.",None),
  M("gm-8",2,"The Kumbh Mela is held once in how many years?","12",[("1","It is not held every year."),("5","It is held once in 12 years."),("100","It is not that rare.")],"The Kumbh Mela is held once in 12 years at Haridwar, Prayagraj, Nashik and Ujjain.",None),
  S("gm-9",2,"A drawing that shows where places are, such as stalls in a mela, is called a ____.",["map","sketch","map or sketch"],"A map or sketch shows where places are.",[("photo","A photo shows how a place looks; a map shows where things are.")]),
  M("gm-10",3,"Why do melas have a police dog with the officer?","Trained dogs help the police find lost things and people",[("To give rides","Police dogs work; they do not give rides."),("To sell toys","Dogs do not sell things."),("To play with children","They are trained to help.")],"Police dogs are trained helpers.",None),
  F("gm-11",3,"If we are lost in a crowd we should run around to find our family.",False,"We should stay where we are and ask a police officer or a volunteer for help."),
  M("gm-12",3,"Which of these is a good way to look after elders at a mela?","Help them walk, find a seat and carry their things",[("Walk ahead quickly without waiting","Elders may be slow and need us to wait."),("Leave them alone","Elders need our care."),("Tell them to stay home","We should include them and help them enjoy.")],"Looking after elders means helping them, as the family did for Dadiji.",None)],
 svgs=[("c3-mela-map","A simple map of a mela ground with entrance, Lost and Found, ambulance, police jeep, fire engine, stalls, food stalls and water point","A map of the mela helps us to find the places.")])
